contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount, address spender) public payable {
        require(amount > 0);
        require(recipient != address(0));

        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        bool reverted1;
        c.approve(spender, amount); // state change, top-level (succeeds)
        try c.transfer(recipient, amount) { reverted1 = false; }
        catch { reverted1 = true; }

        bool reverted2;
        try c.transferFrom(address(this), recipient, amount) { reverted2 = false; }
        catch { reverted2 = true; }

        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        uint256 allowAfter = c.allowance(address(this), spender);

        assert(
            reverted1 && reverted2 &&
            supplyAfter == supplyBefore &&
            balAfter >= balBefore &&
            allowAfter == amount
        );
    }
    receive() external payable {}
}

