contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 initial, uint256 added, uint256 subtracted) public payable {
        require(spender != address(0));
        require(initial <= type(uint256).max - added, "overflow precondition");
        require(subtracted <= initial + added, "underflow precondition");

        c.approve(spender, initial);
        c.increaseAllowance(spender, added);
        c.decreaseAllowance(spender, subtracted);

        uint256 allowAfter = c.allowance(address(this), spender);
        uint256 supplyAfter = c.totalSupply();

        assert(allowAfter == initial + added - subtracted && supplyAfter == 10000000 * 10**18);
    }
    receive() external payable {}
}

