contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public payable {
        require(amount > 0 && amount < c.totalSupply());
        require(to != address(0) && to != address(c));

        // c's owner is the deployer (this contract), but no address is in _allowedRoles,
        // so every transfer must revert with "Unauthorized role".
        bool revertedT;
        try c.transfer(to, amount) { revertedT = false; }
        catch { revertedT = true; }

        bool revertedTF;
        try c.transferFrom(address(this), to, amount) { revertedTF = false; }
        catch { revertedTF = true; }

        assert(revertedT && revertedTF);
    }

    receive() external payable {}
}

